// KMK Madde 20/c Kuralı: Gider ve avans payını ödemeyen kat maliki, ödemede geciktiği günler için aylık yüzde beş (%5) gecikme tazminatı ödemekle yükümlüdür.
const mockOverdueResidents = [
  { daire: 'A Blok D:12', malik: 'Ahmet Yılmaz', anaPara: 2400, gecikmeGun: 28, tel: '0532 555 01 22' },
  { daire: 'B Blok D:04', malik: 'Mehmet Demir', anaPara: 3200, gecikmeGun: 45, tel: '0542 555 01 33' },
  { daire: 'C Blok D:19', malik: 'Selin Karaca', anaPara: 1800, gecikmeGun: 18, tel: '0555 555 01 44' }
];

const processed = mockOverdueResidents.map(r => {
  // Günlük faiz oranı = %5 / 30 gün = %0.166 günlük faiz
  const faizTutari = Math.round((r.anaPara * (0.05 / 30) * r.gecikmeGun) * 100) / 100;
  const toplamBorc = r.anaPara + faizTutari;
  return {
    ...r,
    faizTutari: faizTutari.toLocaleString('tr-TR', { minimumFractionDigits: 2 }),
    toplamBorc: toplamBorc.toLocaleString('tr-TR', { minimumFractionDigits: 2 }),
    anaParaFormatted: r.anaPara.toLocaleString('tr-TR', { minimumFractionDigits: 2 })
  };
});

return [{
  json: {
    timestamp: new Date().toISOString(),
    ay: new Date().toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' }),
    totalBorclu: processed.length,
    residents: processed,
    summary: `KMK m.20 Aidat Hatırlatması: ${processed.length} Bağımsız Bölümde Vadesi Geçmiş Bakiye ve %5 Yasal Faiz Hesaplanmıştır.`
  }
}];
